  const Counter = () => {
    const [[num, str]] = useAtom(waitForAll([asyncAtom, anotherAsyncAtom]))
    return (
      <div>
        num: {num * 1}, str: {str.toLowerCase()}
      </div>
    )
  }

  const { getByText } = render(
    <StrictMode>
      <Provider>
        <Suspense fallback="loading">
          <Counter />
        </Suspense>
      </Provider>
