        <button onClick={() => setValue((v) => v + 1)}>increment</button>
      </>
    )
  }

  const { getByText, findByText } = render(
    <StrictMode>
      <Provider scope={scope}>
        <Suspense fallback="loading">
          <Counter />
        </Suspense>
      </Provider>
    </StrictMode>
